<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();csrf_check();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$act=$_POST['action']??'';if($act==='delete'){$s=db()->prepare('DELETE FROM students WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Student and academic records deleted.');log_event('Student record deleted');header('Location: students.php');exit;}if($act==='save'){$v=[trim((string)($_POST['student_number']??'')),trim((string)($_POST['first_name']??'')),trim((string)($_POST['middle_name']??'')),trim((string)($_POST['last_name']??'')),trim((string)($_POST['gender']??'')),($_POST['date_of_birth']??'')?:null,trim((string)($_POST['contact_number']??'')),trim((string)($_POST['email']??'')),trim((string)($_POST['present_address']??'')),trim((string)($_POST['permanent_address']??'')),($_POST['status']??'Active')];if($v[0]===''||$v[1]===''||$v[3]==='')throw new RuntimeException('Student number, first name, and last name are required.');if(!in_array($v[10],['Active','Inactive','Graduated','Dropped'],true))throw new RuntimeException('Invalid status.');$id=(int)($_POST['id']??0);if($id){$v[]=$id;$s=db()->prepare('UPDATE students SET student_number=?,first_name=?,middle_name=?,last_name=?,gender=?,date_of_birth=?,contact_number=?,email=?,present_address=?,permanent_address=?,status=? WHERE id=?');$s->execute($v);}else{$s=db()->prepare('INSERT INTO students(student_number,first_name,middle_name,last_name,gender,date_of_birth,contact_number,email,present_address,permanent_address,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute($v);}flash('Student saved.');log_event('Student record saved');header('Location: students.php');exit;}}catch(Throwable $ex){error_log((string)$ex);$error=$ex instanceof RuntimeException?$ex->getMessage():'Could not save student. Check for duplicate student numbers.';}}
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM students WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=db()->query('SELECT * FROM students ORDER BY id DESC')->fetchAll();$page_title='Students';require __DIR__.'/includes/header.php';?>
<h1>Student Information and Records</h1><section class="panel"><h2><?= $edit?'Update':'Add New' ?> Student</h2><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><?php foreach(['student_number'=>'Student Number','first_name'=>'First Name','middle_name'=>'Middle Name','last_name'=>'Last Name','gender'=>'Gender','date_of_birth'=>'Date of Birth','contact_number'=>'Contact Number','email'=>'Email','present_address'=>'Present Address','permanent_address'=>'Permanent Address'] as $k=>$label):?><label><?=e($label)?></label><input name="<?=e($k)?>" <?=in_array($k,['student_number','first_name','last_name'])?'required':''?> type="<?= $k==='date_of_birth'?'date':($k==='email'?'email':'text') ?>" value="<?=e($edit[$k]??'')?>"><?php endforeach;?><label>Status</label><select name="status"><?php foreach(['Active','Inactive','Graduated','Dropped'] as $st):?><option <?=($edit['status']??'Active')===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><button>Save Student</button></form></section>
<section class="panel"><h2>All Students</h2><div style="overflow-x:auto"><table><tr><th>Student No.</th><th>Name</th><th>Status</th><th>Academic History</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['student_number'])?></td><td><?=e(trim($r['first_name'].' '.$r['middle_name'].' '.$r['last_name']))?></td><td><?=e($r['status'])?></td><td><a href="academics.php?student_id=<?=e($r['id'])?>">View history</a></td><td><a href="?edit=<?=e($r['id'])?>">Edit</a> <form class="inline" method="post" onsubmit="return confirm('Delete this student and their academic history?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>